import functools, time

def kronometre(fonksyon):
    @functools.wraps(fonksyon)
    def wrapper(*args, **kwargs):
        depa = time.time()
        rezilta = fonksyon(*args, **kwargs)
        print(f"Dire: {time.time() - depa:.2f}s")
        return rezilta
    return wrapper

@kronometre
def kalkile():
    return sum(range(1000000))
